function makeCounter(start = 0) {
  let count = start;                 // private to this counter
  return {
    increment: () => ++count,
    reset: () => { count = start; },
  };
}
const a = makeCounter();
const b = makeCounter(10);
a.increment(); a.increment();
console.log(a.increment(), b.increment()); // 3 11

function memoize(fn) {
  const cache = new Map();           // lives as long as the returned function
  return (n) => {
    if (!cache.has(n)) cache.set(n, fn(n));
    return cache.get(n);
  };
}
const slowSquare = n => { console.log("computing", n); return n * n; };
const fastSquare = memoize(slowSquare);
fastSquare(4);                       // computing 4
console.log(fastSquare(4));          // 16 (cached, no log)

"use strict";
const counter = {
  count: 0,
  increment() { this.count++; return this.count; },
  incrementLater() {
    setTimeout(() => console.log("later:", this.increment()), 0); // arrow keeps this
  },
};

console.log(counter.increment());       // 1  (method call)

const detached = counter.increment;
try { detached(); }                     // plain call: this is undefined
catch (e) { console.log(e.constructor.name); } // TypeError

const bound = counter.increment.bind(counter);
console.log(bound());                   // 2

function describe(prefix) { return `${prefix} ${this.count}`; }
console.log(describe.call(counter, "count is")); // count is 2

