const sleep = ms => new Promise(r => setTimeout(r, ms));

// Fake paginated API: 3 pages of 2 items
async function fetchPage(cursor = 0) {
  await sleep(20);
  const items = [`item${cursor * 2}`, `item${cursor * 2 + 1}`];
  return { items, next: cursor < 2 ? cursor + 1 : null };
}

async function* allItems() {
  let cursor = 0;
  while (cursor !== null) {
    const page = await fetchPage(cursor);   // fetched only when needed
    yield* page.items;
    cursor = page.next;
  }
}

for await (const item of allItems()) {
  console.log(item);
  if (item === "item3") break;               // stops: page 3 is never fetched
}

const everything = await Array.fromAsync(allItems());
console.log(everything.length);              // 6

// Run with: node perf.mjs
const N = 20_000;
const ids = Array.from({ length: N }, (_, i) => i);
const wanted = Array.from({ length: N }, (_, i) => i * 2);

function time(label, fn) {
  performance.mark(`${label}-start`);
  const result = fn();
  const m = performance.measure(label, `${label}-start`);
  console.log(`${label}: ${m.duration.toFixed(1)} ms (${result} hits)`);
}

time("array.includes (O(n^2))", () =>
  wanted.filter(id => ids.includes(id)).length);

time("Set.has (O(n))", () => {
  const idSet = new Set(ids);
  return wanted.filter(id => idSet.has(id)).length;
});
