import { Worker, isMainThread, workerData } from "node:worker_threads";

if (isMainThread) {
  const shared = new SharedArrayBuffer(8);       // two Int32 slots
  const view = new Int32Array(shared);
  const workers = Array.from({ length: 4 }, () =>
    new Worker(new URL(import.meta.url), { workerData: shared }));
  await Promise.all(workers.map(w => new Promise(r => w.on("exit", r))));

  console.log("atomic:", Atomics.load(view, 0)); // atomic: 400000 (always)
  console.log("racy:  ", view[1]);               // racy: often less than 400000
} else {
  const view = new Int32Array(workerData);       // same memory, not a copy
  for (let i = 0; i < 100_000; i++) {
    Atomics.add(view, 0, 1);                     // indivisible read-modify-write
    view[1]++;                                   // data race: updates can be lost
  }
}
